U='u8'
def H(s,k,en,ur,ps,**m): add(s,k,en,ur,ps,kind='heading',**m)
NOTE=' Screenshots are not reproduced; each screenshot is redrawn as simplified coded SVG with the legible printed labels. Watermark, border lines, page-edge shadows and handwriting are excluded.'
def fin(s,note):
    s['sourceNote']=note+NOTE; s['vocabulary']={}; save(s)
def shell(w,h,title,body,label):
    b=f'<rect x="5" y="5" width="{w-10}" height="{h-10}" fill="#f4f7fb" stroke="#555"/><rect x="5" y="5" width="{w-10}" height="16" fill="#cfd9ea" stroke="#555"/>'+T(w/2,17,title,8,'middle',400)
    return svg(w,h,label,b+body)
def ribbon(tabs,y=30):
    b='<circle cx="22" cy="%d" r="8" fill="#d9b04a" stroke="#555"/>'%(y+5)
    for k,t in enumerate(tabs): b+=T(45+k*68,y+9,t,8,'start',700)
    return b+f'<rect x="10" y="{y+16}" width="420" height="36" fill="#e8eef8" stroke="#aaa"/>'
def dview(rows,key=False,types=False,two=False):
    body=ribbon(['Home','Create','External Data','Database Tools','Design'])+'<rect x="10" y="95" width="100" height="100" fill="#fff" stroke="#888"/>'+T(15,108,'All Tables',8,'start',700)+T(15,124,'Student',8,'start',700)+T(30,136,'Student : Table',8,'start',400)+T(15,150,'Exam',8,'start',700)+T(30,162,'Exam : Table',8,'start',400)
    body+='<rect x="115" y="95" width="315" height="62" fill="#fff" stroke="#888"/>'+T(135,107,'Field Name',8,'start',700)+T(240,107,'Data Type',8,'start',700)+T(340,107,'Description',8,'start',700)
    for k,(n,t) in enumerate(rows):
        body+=T(135,120+k*10,n,7,'start',700)+T(240,120+k*10,t,7,'start',400)
    if key: body+='<rect x="120" y="113" width="8" height="8" fill="#d9b04a" stroke="#555"/>'
    body+='<rect x="115" y="160" width="315" height="40" fill="#fff" stroke="#888"/>'+T(120,172,'General  Lookup',7,'start',400)+T(120,184,'Field Size    Long Integer',7,'start',400)
    return shell(445,215,'Student : Database (Access 2007) — Microsoft Access',body,'Access Design View: '+', '.join(n for n,_ in rows))
